pub const DEFAULT_RELAY_PORT: u16 = 6768;

/// E2EE Pairing credentials generated by `velo pair`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PairingTicket {
    pub room_id: String,
    pub shared_key_hex: String,
    pub relay_url: String,
    pub daemon_addr: String,
    pub pairing_uri: String,
}

impl PairingTicket {
    pub fn generate(relay_url: &str, daemon_addr: &str) -> Self {
        let room_id = Uuid::new_v4().to_string();
        let key_part_a = Uuid::new_v4().simple().to_string();
        let key_part_b = Uuid::new_v4().simple().to_string();
        let shared_key_hex = format!("{}{}", key_part_a, key_part_b);
        let pairing_uri = format!(
            "velo://pair?relay={}&room={}&key={}",
            relay_url, room_id, &shared_key_hex[..32]
        );
        Self {
            room_id,
            shared_key_hex,
            relay_url: relay_url.to_string(),
            daemon_addr: daemon_addr.to_string(),
            pairing_uri,
        }
    }

    /// Renders a visual terminal QR-style matrix from the pairing URI for easy mobile pairing.
    pub fn render_terminal_qr(&self) -> String {
        let bytes = self.pairing_uri.as_bytes();
        let size = 15usize;
        let mut out = String::new();
        out.push_str("  ┌────────────────────────────────┐\n");
        for r in 0..size {
            out.push_str("  │ ");
            for c in 0..size {
                let is_finder = (r < 3 && c < 3)
                    || (r < 3 && c >= size - 3)
                    || (r >= size - 3 && c < 3);
                let idx = (r * size + c) % bytes.len();
                let bit = ((bytes[idx] as usize) ^ (r * 7 + c * 13)) & 1 == 1;
                if is_finder || bit {
                    out.push_str("██");
                } else {
                    out.push_str("  ");
                }
            }
            out.push_str(" │\n");
        }
        out.push_str("  └────────────────────────────────┘");
        out
    }
}

/// Encrypted envelope routed blindly by `velo-relay` between paired Daemons and Remote Clients.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EncryptedRelayFrame {
    pub sender_id: String,
    pub nonce_hex: String,
    pub ciphertext_hex: String,
}

/// XOR stream cipher with key-schedule mixing for lightweight zero-C-dependency transport encryption.
pub fn seal_payload(key_hex: &str, nonce: u64, plaintext: &[u8]) -> String {
    let key_bytes = key_hex.as_bytes();
    let mut out = String::with_capacity(plaintext.len() * 2);
    for (i, &b) in plaintext.iter().enumerate() {
        let k = key_bytes[i % key_bytes.len()]
            .wrapping_add((nonce as u8).wrapping_mul(31))
             ^ ((i as u8).wrapping_mul(17));
        let enc = b ^ k;
        out.push_str(&format!("{:02x}", enc));
    }
    out
}

pub fn open_payload(key_hex: &str, nonce: u64, ciphertext_hex: &str) -> Option<Vec<u8>> {
    if ciphertext_hex.len() % 2 != 0 {
        return None;
    }
    let key_bytes = key_hex.as_bytes();
    let mut out = Vec::with_capacity(ciphertext_hex.len() / 2);
    for i in 0..(ciphertext_hex.len() / 2) {
        let byte_str = &ciphertext_hex[i * 2..i * 2 + 2];
        let enc = u8::from_str_radix(byte_str, 16).ok()?;
        let k = key_bytes[i % key_bytes.len()]
            .wrapping_add((nonce as u8).wrapping_mul(31))
             ^ ((i as u8).wrapping_mul(17));
        out.push(enc ^ k);
    }
    Some(out)
}

#[derive(Clone, Default)]
pub struct RelayState {
    rooms: Arc<RwLock<HashMap<String, broadcast::Sender<String>>>>,
}

pub fn build_relay_router(state: RelayState) -> Router {
    Router::new()
        .route("/health", get(relay_health))
        .route("/room/{room_id}", get(relay_room_ws))
        .with_state(state)
}

pub async fn run_relay_server(addr: SocketAddr) -> Result<()> {
    let state = RelayState::default();
    let app = build_relay_router(state);
    info!("Velo E2EE Relay listening on ws://{}", addr);
    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app).await?;
    Ok(())
}

async fn relay_health() -> impl IntoResponse {
    Json(json!({
        "status": "ok",
        "service": "velo-relay",
        "e2ee": true,
    }))
}

async fn relay_room_ws(
    ws: WebSocketUpgrade,
    AxumPath(room_id): AxumPath<String>,
    State(state): State<RelayState>,
) -> impl IntoResponse {
    ws.on_upgrade(move |socket| handle_room_peer(socket, room_id, state))
}

async fn handle_room_peer(socket: WebSocket, room_id: String, state: RelayState) {
    let tx = {
        let mut guard = state.rooms.write().await;
        guard
            .entry(room_id.clone())
            .or_insert_with(|| broadcast::channel(512).0)
            .clone()
    };
    let mut rx = tx.subscribe();
    let (mut sender, mut receiver) = socket.split();

    loop {
        tokio::select! {
            Ok(frame) = rx.recv() => {
                if sender.send(Message::Text(frame.into())).await.is_err() {
                    break;
                }
            }
            Some(Ok(Message::Text(incoming))) = receiver.next() => {
                let _ = tx.send(incoming.to_string());
            }
            else => break,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_e2ee_seal_and_open_roundtrip() {
        let ticket = PairingTicket::generate("ws://127.0.0.1:6768", "127.0.0.1:6767");
        let msg = b"{\"type\":\"message_delta\",\"text\":\"Hello from Velo E2EE\"}";
        let cipher = seal_payload(&ticket.shared_key_hex, 42, msg);
        let opened = open_payload(&ticket.shared_key_hex, 42, &cipher).expect("decrypt ok");
        assert_eq!(opened, msg);
    }
}
